        $fields = [];
        $model = new MessageModel($fullName, $fields);
        $fileModel->messages["." . $fullName] = $model;
        foreach ($rawFields as $fieldBytes) {
            $field = self::parseField($fieldBytes);
            $fields[$field->number] = $field;
