                $number = $fval;
            } elseif ($fnum === 4) {
                $label = $fval;
            } elseif ($fnum === 5) {
                $fieldType = $fval;
            } elseif ($fnum === 6) {
                $typeName = $fval;
            }
        }
        return new FieldModel($number, $name, $fieldType, $label, $typeName);
    }

